using System;using System.IO;using System.Linq;using System.Globalization;using PersistentFlight.Regions;
class GoalTemplateTests {
 static int checks;static void Check(bool b,string s){checks++;if(!b)throw new Exception(s);}static void Reject(Action a,string s){bool denied=false;try{a();}catch{denied=true;}Check(denied,s);}
 static MissionTemplate T(TemplateGoal goal,double altitude=0){return new MissionTemplate{Id=Guid.NewGuid(),Name="Goal α",Body="Kerbin",SourceSMA=800000,SourceEcc=.1,SourceInclination=5,Goal=goal,TargetAltitude=altitude};}
 static GoalOrbitInput O(){double sma=800000,mu=3.5316e12;return new GoalOrbitInput{Mu=mu,BodyRadius=600000,AtmosphereDepth=70000,SphereOfInfluence=84159286,SMA=sma,Eccentricity=.1,Period=2*Math.PI*Math.Sqrt(sma*sma*sma/mu),TimeToApoapsis=90,TimeToPeriapsis=500,Now=10000};}
 static void OrbitCheck(TemplateGoal goal,double altitude,double expectedPe,double expectedAp,int sign){var o=O();var p=GoalOrbitMath.Calculate(T(goal,altitude),o);Check(Math.Sign(p.Prograde)==sign,"Wrong burn direction");double r=GoalOrbitMath.AtApoapsis(goal)?o.SMA*(1+o.Eccentricity):o.SMA*(1-o.Eccentricity);double v=Math.Sqrt(o.Mu*(2/r-1/o.SMA))+p.Prograde;double a=1/(2/r-v*v/o.Mu);double h=r*v;double e=Math.Sqrt(Math.Max(0,1-h*h/(o.Mu*a)));Check(Math.Abs(a*(1-e)-o.BodyRadius-expectedPe)<.1&&Math.Abs(a*(1+e)-o.BodyRadius-expectedAp)<.1,"Velocity/energy orbit does not meet requested apsides");Check(Math.Abs(p.PeriapsisAltitude-expectedPe)<.001&&Math.Abs(p.ApoapsisAltitude-expectedAp)<.001,"Preview radii wrong");Check(p.UT==o.Now+(GoalOrbitMath.AtApoapsis(goal)?90:500),"Not at requested apsis");}
 static int Main(){string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"PF-Goal-Tests-"+Guid.NewGuid().ToString("N"));try{
  OrbitCheck(TemplateGoal.CircularizeApoapsis,0,280000,280000,1);OrbitCheck(TemplateGoal.CircularizePeriapsis,0,120000,120000,-1);
  OrbitCheck(TemplateGoal.OppositeFromApoapsis,160000,160000,280000,1);OrbitCheck(TemplateGoal.OppositeFromApoapsis,100000,100000,280000,-1);
  OrbitCheck(TemplateGoal.OppositeFromPeriapsis,400000,120000,400000,1);OrbitCheck(TemplateGoal.OppositeFromPeriapsis,220000,120000,220000,-1);
  foreach(var kind in new[]{TemplateGoal.CircularizeApoapsis,TemplateGoal.CircularizePeriapsis,TemplateGoal.OppositeFromApoapsis,TemplateGoal.OppositeFromPeriapsis}){var t=T(kind,kind==TemplateGoal.OppositeFromApoapsis?160000:kind==TemplateGoal.OppositeFromPeriapsis?400000:0);string encoded=MissionTemplateStore.Encode(t);var copy=MissionTemplateStore.Decode(encoded);Check(copy.Goal==kind&&copy.TargetAltitude==t.TargetAltitude&&copy.Steps.Count==0,"Goal roundtrip changed purpose");CultureInfo.CurrentCulture=new CultureInfo("fr-FR");Check(MissionTemplateStore.Encode(copy)==encoded,"Locale changed goal file");MissionTemplateStore.Save(folder,t);Check(MissionTemplateStore.Load(folder,t.Id).Goal==kind,"Goal file persistence failed");}
  string[] errors;Check(MissionTemplateStore.List(folder,out errors).Length==4&&errors.Length==0,"Mixed library failed");
  var goal=T(TemplateGoal.CircularizeApoapsis);var o=O();o.TimeToApoapsis=10;var p=GoalOrbitMath.Calculate(goal,o);Check(Math.Abs(p.UT-(10010+o.Period))<1e-7,"Near apsis did not wait one orbit");o.TimeToApoapsis=60;Check(GoalOrbitMath.Calculate(goal,o).UT==10060,"Exact 60 seconds skipped");
  var changed=O();changed.SMA=900000;changed.Period=2*Math.PI*Math.Sqrt(Math.Pow(changed.SMA,3)/changed.Mu);Check(Math.Abs(GoalOrbitMath.Calculate(goal,changed).Prograde-GoalOrbitMath.Calculate(goal,O()).Prograde)>1,"Destination orbit did not recompute burn");
  var encounter=O();encounter.BodyChangeUT=10080;Reject(()=>GoalOrbitMath.Calculate(goal,encounter),"Apsis after body encounter accepted");encounter.BodyChangeUT=10090;Reject(()=>GoalOrbitMath.Calculate(goal,encounter),"Apsis at body encounter accepted");encounter.BodyChangeUT=10100;Check(GoalOrbitMath.Calculate(goal,encounter).UT==10090,"Safe apsis before encounter rejected");
  foreach(double n in new[]{Double.NaN,Double.PositiveInfinity,-1,1}){var bad=O();bad.Eccentricity=n;Reject(()=>GoalOrbitMath.Calculate(goal,bad),"Invalid eccentricity accepted");}
  foreach(double n in new[]{Double.NaN,-1,1e10}){var bad=O();bad.TimeToApoapsis=n;Reject(()=>GoalOrbitMath.Calculate(goal,bad),"Invalid apsis time accepted");}
  Reject(()=>GoalOrbitMath.Calculate(T(TemplateGoal.OppositeFromApoapsis,69000),O()),"Atmospheric target accepted");Reject(()=>GoalOrbitMath.Calculate(T(TemplateGoal.OppositeFromPeriapsis,90000000),O()),"SOI escape accepted");Reject(()=>GoalOrbitMath.Calculate(T(TemplateGoal.OppositeFromApoapsis,400000),O()),"Periapsis above fixed apoapsis accepted");Reject(()=>GoalOrbitMath.Calculate(T(TemplateGoal.OppositeFromPeriapsis,100000),O()),"Apoapsis below fixed periapsis accepted");
  var circular=O();circular.Eccentricity=0;Reject(()=>GoalOrbitMath.Calculate(goal,circular),"Zero burn accepted");var atmosphere=O();atmosphere.Eccentricity=.2;Reject(()=>GoalOrbitMath.Calculate(goal,atmosphere),"Current atmospheric periapsis accepted");var huge=O();huge.Now=Double.MaxValue;Reject(()=>GoalOrbitMath.Calculate(goal,huge),"Unrepresentable UT accepted");
  Reject(()=>T((TemplateGoal)99).Validate(),"Unknown goal accepted");Reject(()=>T(TemplateGoal.CircularizeApoapsis,1).Validate(),"Circle stored arbitrary altitude");Reject(()=>T(TemplateGoal.OppositeFromApoapsis,0).Validate(),"Empty target accepted");Reject(()=>goal.Times(10000,120),"Goal reused sequence timing");var both=T(TemplateGoal.CircularizeApoapsis);both.Steps.Add(new TemplateStep{Prograde=10});Reject(()=>both.Validate(),"Goal containing copied burns accepted");
  string text=MissionTemplateStore.Encode(goal);Reject(()=>MissionTemplateStore.Decode(text.Replace("800000","800001")),"Damaged goal accepted");Reject(()=>MissionTemplateStore.Decode(text.Replace("PFMT2","PFMT9")),"Unknown file version accepted");Reject(()=>MissionTemplateStore.Decode(text+"extra"),"Trailing goal payload accepted");
  Console.WriteLine("PASS "+checks+" orbital goal checks");return 0;
 }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}finally{Console.WriteLine("Evidence: "+folder);}}
}
